import React, { useState } from 'react';
import AuraCanvas from '../components/AuraCanvas';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const [inputOpen, setInputOpen] = useState(false);
  const { addThought } = useThoughts();

  const submit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id: Date.now(), user_text: text, ...ai, date: new Date().toISOString() };
      addThought(entry);
      setResult(entry);
      setInputOpen(false);
    } catch { setError('Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={() => { setResult(null); setText(''); }} setPage={setPage} />;

  return (
    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#0d0d0d' }}>
      <AuraCanvas hues={[210, 240]} intensity={0.65} speed={0.45} />

      {/* Brand — small, top left */}
      <div style={{ position: 'absolute', top: 28, left: 24, zIndex: 10 }}>
        <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 11, letterSpacing: '0.2em', textTransform: 'uppercase', color: 'rgba(240,237,230,0.4)' }}>
          Spiral
        </span>
      </div>

      {streak > 0 && (
        <div style={{ position: 'absolute', top: 26, right: 24, zIndex: 10 }}>
          <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 10, color: 'rgba(240,237,230,0.35)', letterSpacing: '0.08em' }}>
            🔥 {streak}
          </span>
        </div>
      )}

      {/* Central hero text — like "ARTICLES" centred on the face */}
      {!inputOpen && (
        <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', zIndex: 10, animation: 'fadeIn .8s ease both', textAlign: 'center', padding: '0 32px' }}>
          <p style={{ fontFamily: 'DM Mono, monospace', fontSize: 10, letterSpacing: '0.24em', textTransform: 'uppercase', color: 'rgba(240,237,230,0.35)', marginBottom: 20 }}>
            KBT · Tankeanalys
          </p>
          <h1 style={{ fontSize: 'clamp(42px,11vw,72px)', fontWeight: 700, letterSpacing: '-0.04em', lineHeight: 1.05, color: '#f0ede6', marginBottom: 12 }}>
            Vad tänker<br/>du på?
          </h1>
          <p style={{ fontSize: 14, fontWeight: 300, color: 'rgba(240,237,230,0.45)', lineHeight: 1.7, maxWidth: 280, marginBottom: 48 }}>
            Skriv ner vad som snurrar. AI:n identifierar tankefällan och hjälper dig se klart.
          </p>

          {/* Two big round buttons — like Talk-it-out's circular UI */}
          <div style={{ display: 'flex', gap: 12 }}>
            <button onClick={() => setInputOpen(true)} style={{
              width: 64, height: 64, borderRadius: '50%',
              background: 'rgba(240,237,230,0.92)',
              color: '#0d0d0d', fontSize: 22,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              boxShadow: '0 8px 32px rgba(0,0,0,0.4)',
              transition: 'transform .2s',
            }}
            onMouseEnter={e => e.currentTarget.style.transform = 'scale(1.06)'}
            onMouseLeave={e => e.currentTarget.style.transform = 'scale(1)'}>
              ✎
            </button>
            <button onClick={() => setPage('checkin')} style={{
              width: 64, height: 64, borderRadius: '50%',
              background: 'rgba(255,255,255,0.1)',
              border: '1px solid rgba(255,255,255,0.15)',
              color: 'rgba(240,237,230,0.7)', fontSize: 22,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              backdropFilter: 'blur(12px)',
              transition: 'transform .2s',
            }}
            onMouseEnter={e => e.currentTarget.style.transform = 'scale(1.06)'}
            onMouseLeave={e => e.currentTarget.style.transform = 'scale(1)'}>
              ◎
            </button>
          </div>
        </div>
      )}

      {/* Input — slides up from bottom when open */}
      {inputOpen && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 20, display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', animation: 'fadeUp .4s cubic-bezier(0.16,1,0.3,1) both' }}>
          {/* Tap outside to close */}
          <div onClick={() => setInputOpen(false)} style={{ position: 'absolute', inset: 0 }} />

          <div style={{ position: 'relative', margin: '0 12px 24px', background: 'rgba(20,20,20,0.92)', backdropFilter: 'blur(32px)', borderRadius: 28, border: '1px solid rgba(255,255,255,0.1)', overflow: 'hidden' }}>
            <div style={{ padding: '20px 20px 0' }}>
              <p style={{ fontFamily: 'DM Mono, monospace', fontSize: 9, letterSpacing: '0.2em', textTransform: 'uppercase', color: 'rgba(240,237,230,0.3)', marginBottom: 12 }}>
                Vad tänker du på?
              </p>
              <textarea
                autoFocus
                value={text}
                onChange={e => setText(e.target.value)}
                maxLength={1000}
                placeholder="Skriv fritt — inga rätta svar..."
                style={{ width: '100%', minHeight: 120, background: 'transparent', border: 'none', color: '#f0ede6', fontSize: 16, fontWeight: 300, lineHeight: 1.75, resize: 'none', outline: 'none' }}
              />
            </div>
            <div style={{ padding: '12px 20px 20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid rgba(255,255,255,0.07)' }}>
              <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 9, color: 'rgba(240,237,230,0.2)' }}>{text.length}/1000</span>
              <button onClick={submit} disabled={!text.trim() || loading} style={{
                padding: '11px 28px', borderRadius: 100,
                background: text.trim() && !loading ? '#f0ede6' : 'rgba(255,255,255,0.08)',
                color: text.trim() && !loading ? '#0d0d0d' : 'rgba(240,237,230,0.25)',
                fontSize: 13, fontWeight: 700, border: 'none', transition: 'all .2s',
              }}>
                {loading
                  ? <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}><span style={{ width: 10, height: 10, border: '2px solid rgba(13,13,13,0.2)', borderTopColor: '#0d0d0d', borderRadius: '50%', display: 'inline-block', animation: 'spin .7s linear infinite' }} />Analyserar</span>
                  : 'Analysera →'}
              </button>
            </div>
            {error && <p style={{ padding: '0 20px 16px', fontSize: 12, color: 'rgba(220,100,100,0.8)' }}>{error}</p>}
          </div>
        </div>
      )}
    </div>
  );
}

